int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *md_ctx = NULL;
    const EVP_MD *md = NULL;
    unsigned char *sig = NULL;
    int sig_len = 0;
    int ret = -1;

    if (!a || !signature || !asn || !pkey) {
        return -1;
    }

    md = EVP_get_digestbynid(a->algorithm);
    if (!md) {
        return -1;
    }

    md_ctx = EVP_MD_CTX_new();
    if (!md_ctx) {
        goto err;
    }

    if (!EVP_DigestVerifyInit(md_ctx, NULL, md, NULL, pkey)) {
        goto err;
    }

    if (!EVP_DigestVerifyUpdate(md_ctx, asn, it->item.size)) {
        goto err;
    }

    sig = (unsigned char *)signature->data;
    sig_len = signature->length;

    ret = EVP_DigestVerifyFinal(md_ctx, sig, sig_len);

