        EVP_MD_CTX_free(md_ctx);
    }

    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !asn || !pkey)
        return -1;

    if (!(md = EVP_get_digestbyname(OBJ_nid2ln(a->algorithm)))) {
        ERR_set_mark();
        return -1;
    }

    if (!(ctx = EVP_MD_CTX_create()))
        return -1;

    if (!EVP_VerifyInit_ex(ctx, md, NULL, pkey, NULL, 0))
        goto err;

    if (!it || !asn1_item_ex_i2d((ASN1_VALUE **)&asn, it, NULL, 0))
        goto err;

    if (!EVP_VerifyUpdate(ctx, asn, it->size))
        goto err;

    if (EVP_VerifyFinal(ctx, signature->data, signature->length, pkey) <= 0)
        goto err;

    ret = 1;
err:
    EVP_MD_CTX_free(ctx);
    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !asn || !pkey) {
        return -1;
    }

    if (a->parameter) {
        ASN1_TYPE *typ = a->parameter;
        if (typ->type != V_ASN1_NULL) {
            return -1;
        }
    }

    md = EVP_get_digestbyname(OBJ_nid2ln(a->algorithm));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx) {
        goto cleanup;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL)) {
        goto cleanup;
    }

    if (!ASN1_item_digest_update(ctx, it, asn)) {
        goto cleanup;
    }

    if (EVP_VerifyFinal(ctx, signature->data, (size_t)signature->length, pkey) != 1) {
        goto cleanup;
    }

    ret = 1;

cleanup:
    if (ctx) {
        EVP_MD_CTX_free(ctx);
    }

    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !pkey || !asn)
        return -1;

    if (!(ctx = EVP_MD_CTX_new()))
        return -1;

    if (!X509_ALGOR_get_md(a, &md)) {
        EVP_MD_CTX_free(ctx);
        return -1;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL)) {
        EVP_MD_CTX_free(ctx);
        return -1;
    }

    if (!EVP_VerifyUpdate(ctx, asn, it->it->size_func(asn))) {
        EVP_MD_CTX_free(ctx);
        return -1;
    }

    if (signature->length < 0 || signature->length > it->it->size_func(asn)) {
        EVP_MD_CTX_free(ctx);
        return -1;
    }

    ret = EVP_VerifyFinal(ctx, signature->data, signature->length, pkey);

    EVP_MD_CTX_free(ctx);

    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;
    unsigned char *sig = NULL;
    int sig_len = 0;

    if (!a || !signature || !asn || !pkey) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx)
        goto end;

    if (!OBJ_sn2nid(a->algorithm)) {
        goto end;
    }

    md = EVP_get_digestbynid(OBJ_sn2nid(a->algorithm));
    if (!md) {
        goto end;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL)) {
        goto end;
    }

    if (!EVP_VerifyUpdate(ctx, asn, it->it->length)) {
        goto end;
    }

    sig = signature->data;
    sig_len = signature->length;

    if (!sig || sig_len <= 0) {
        goto end;
    }

    ret = EVP_VerifyFinal(ctx, sig, sig_len, pkey);
    if (ret <= 0) {
        ret = 0;
    } else {
        ret = 1;
    }

end:
    if (ctx)
        EVP_MD_CTX_free(ctx);

    return ret;
}
